def make_question(index, row):
    tag, prompt, options, answer, reason = row
    opts = [{"id": chr(65+i), "text": text} for i, text in enumerate(options)]
    aid = next(o["id"] for o in opts if o["text"] == answer)
    refs = [{"url": u, "title": f"{t}；僅研究公開題型與能力方向，未複製原題。", "year": "113-114", "subject": "social", "locator": l, "observedPattern": "公立學校社會科公開試題常見的天氣、氣候圖與長期資料判讀能力，經本題重新設計。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for u,t,l in SOURCES]
    steps = [f"讀題定位：圈出「{tag}」的時間尺度、氣溫、雨量、季節、地形與資料期間。", f"整理證據：分清短期天氣、長期氣候、平均值與極端事件；核心理由是「{reason}」。", f"核對正解：選項 {aid}「{answer}」符合氣候資料的讀法與題目限制。", "排除誘答：檢查是否把單日、單站、平均值或圖表外觀直接外推成全年或全臺結論。", "結論回查：確認資料年份、測站、尺度與統計方法可比；改變期間後要重新判讀。"]
    return {"id": f"question-social-content-geo-ac-iv-1-{index}", "subject": "social", "type": "single-choice", "prompt": prompt, "options": opts, "knowledgeIds": ["kg-social-content-geo-ac-iv-1"], "difficulty": "medium", "answer": {"value": aid, "explanation": reason}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "高雄市立鹽埕國中三年級社會科公開段考；本題只研究公開試題能力結構與資料型態。", "authoringNote": "依官方課綱、單元 KG 與三個公立學校公開來源的題型方向，獨立改寫天氣與氣候資料判讀情境；未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-09", "lessonId": "lesson-social-content-geo-ac-iv-1", "examPatternRefs": refs, "solutionStrategy": "先區分天氣與氣候的時間尺度，再讀溫度、雨量與季節分布，最後檢查測站、期間、地形與統計方法。", "solutionSteps": steps}

for index, row in enumerate(DATA, 1):
    (OUT / f"question-social-content-geo-ac-iv-1-{index}.json").write_text(json.dumps(make_question(index, row), ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
